insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('business-workstyle-reform', '00000000-0000-4000-8000-2d6d3f771b98', '働き方改革の年表', '過労問題をきっかけにした法整備から、コロナ下の在宅勤務、2024年問題まで。法制度・企業の現場・働き手の意識の3層を重ねて、日本の働き方が何を変えて、何を積み残してきたのかを見ていく年表です。制度と現場のあいだのギャップにも目を向けます。', 'business', 'ja', 'public', 's_business-workstyle-reform', 2016, 2025, 'business-workstyle-reform')
on conflict (slug) do update set owner_id = excluded.owner_id, title = excluded.title, description = excluded.description, category = excluded.category,
